<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Fresh Pantry — Discover Everyday Deliciousness</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Nunito:wght@600;700;800&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
  <style>
    :root {
      --bg-main: oklch(97% 0.02 95);
      --bg-soft: oklch(99% 0.01 95);
      --surface: oklch(100% 0 0);
      --text: oklch(27% 0.03 145);
      --text-soft: oklch(45% 0.03 145);
      --primary: oklch(62% 0.16 150);
      --primary-deep: oklch(52% 0.14 150);
      --accent: oklch(76% 0.16 72);
      --accent-2: oklch(72% 0.14 42);
      --line: oklch(90% 0.02 100);
      --shadow: 0 12px 30px oklch(25% 0.03 150 / 0.08);
      --radius-lg: 24px;
      --radius-md: 16px;
      --radius-sm: 12px;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      font-family: "Inter", system-ui, -apple-system, sans-serif;
      color: var(--text);
      background: linear-gradient(180deg, var(--bg-main) 0%, oklch(96% 0.02 102) 100%);
      line-height: 1.5;
    }

    .container {
      width: min(1120px, calc(100% - 2rem));
      margin-inline: auto;
    }

    h1, h2, h3, .logo, .stat-value {
      font-family: "Nunito", "Inter", sans-serif;
      letter-spacing: -0.02em;
      margin: 0;
    }

    a { color: inherit; text-decoration: none; }

    header {
      position: sticky;
      top: 0;
      z-index: 10;
      backdrop-filter: blur(10px);
      background: oklch(99% 0.01 95 / 0.86);
      border-bottom: 1px solid var(--line);
    }

    .nav {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0.85rem 0;
      gap: 1rem;
    }

    .logo {
      font-weight: 800;
      font-size: 1.35rem;
      display: flex;
      align-items: center;
      gap: 0.45rem;
      color: var(--primary-deep);
    }

    .logo-badge {
      width: 32px;
      height: 32px;
      border-radius: 10px;
      display: grid;
      place-items: center;
      background: linear-gradient(135deg, var(--primary), var(--accent));
      color: white;
      font-size: 1rem;
    }

    .nav-links {
      display: flex;
      gap: 1rem;
      flex-wrap: wrap;
    }

    .nav-links a {
      padding: 0.5rem 0.8rem;
      border-radius: 999px;
      font-weight: 600;
      color: var(--text-soft);
      transition: 0.2s ease;
    }

    .nav-links a:hover {
      color: var(--primary-deep);
      background: oklch(94% 0.04 145 / 0.45);
    }

    .cta-btn {
      background: var(--primary);
      color: white;
      border: none;
      border-radius: 999px;
      padding: 0.7rem 1.1rem;
      font-weight: 700;
      cursor: pointer;
      box-shadow: var(--shadow);
    }

    section { padding: 3.5rem 0; }

    .hero-grid {
      display: grid;
      grid-template-columns: 1.1fr 0.9fr;
      align-items: center;
      gap: 2rem;
    }

    .eyebrow {
      display: inline-block;
      background: oklch(94% 0.05 80);
      color: oklch(38% 0.09 78);
      padding: 0.35rem 0.75rem;
      border-radius: 999px;
      font-size: 0.82rem;
      font-weight: 700;
      margin-bottom: 1rem;
    }

    h1 {
      font-size: clamp(2rem, 4vw, 3.4rem);
      line-height: 1.06;
      margin-bottom: 1rem;
      color: oklch(28% 0.04 145);
    }

    .hero p {
      color: var(--text-soft);
      max-width: 55ch;
      margin-bottom: 1.5rem;
      font-size: 1.05rem;
    }

    .hero-actions {
      display: flex;
      gap: 0.8rem;
      flex-wrap: wrap;
    }

    .btn-secondary {
      background: var(--surface);
      color: var(--primary-deep);
      border: 1px solid var(--line);
      border-radius: 999px;
      padding: 0.68rem 1.1rem;
      font-weight: 700;
      cursor: pointer;
    }

    .hero-image {
      border-radius: var(--radius-lg);
      overflow: hidden;
      box-shadow: var(--shadow);
      min-height: 330px;
      background: center/cover no-repeat url('https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=1200&q=80');
      position: relative;
    }

    .hero-image::after {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(180deg, transparent 35%, oklch(28% 0.04 145 / 0.2));
    }

    .section-head {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      align-items: end;
      margin-bottom: 1.25rem;
    }

    .section-head h2 {
      font-size: clamp(1.4rem, 2.4vw, 2.1rem);
      color: oklch(30% 0.04 145);
    }

    .section-head p { margin: 0; color: var(--text-soft); }

    .highlights {
      background: linear-gradient(135deg, oklch(62% 0.16 150), oklch(55% 0.14 132));
      border-radius: var(--radius-lg);
      color: white;
      box-shadow: var(--shadow);
    }

    .stats {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 1rem;
      padding: 1.8rem;
    }

    .stat {
      background: oklch(100% 0 0 / 0.12);
      border: 1px solid oklch(100% 0 0 / 0.2);
      border-radius: var(--radius-md);
      padding: 1rem;
      text-align: center;
    }

    .stat-value { font-size: 1.8rem; font-weight: 800; }
    .stat-label { font-size: 0.9rem; opacity: 0.95; }

    .carousel-wrap {
      position: relative;
      margin-top: 1rem;
    }

    .carousel {
      display: flex;
      gap: 1rem;
      overflow-x: auto;
      scroll-behavior: smooth;
      scrollbar-width: none;
      padding: 0.2rem 0.1rem 0.6rem;
    }

    .carousel::-webkit-scrollbar { display: none; }

    .product-card {
      min-width: clamp(210px, 26vw, 250px);
      background: var(--surface);
      border-radius: var(--radius-md);
      border: 1px solid var(--line);
      box-shadow: var(--shadow);
      overflow: hidden;
      flex: 0 0 auto;
    }

    .product-card img {
      width: 100%;
      height: 165px;
      object-fit: cover;
      display: block;
    }

    .product-body { padding: 0.85rem; }
    .product-name { font-weight: 700; margin-bottom: 0.3rem; }
    .price { color: var(--primary-deep); font-weight: 800; }

    .carousel-controls {
      display: flex;
      gap: 0.6rem;
      margin-top: 1rem;
      justify-content: flex-end;
    }

    .icon-btn {
      border: 1px solid var(--line);
      background: var(--surface);
      width: 42px;
      height: 42px;
      border-radius: 50%;
      font-size: 1.1rem;
      cursor: pointer;
      color: var(--text-soft);
    }

    .icon-btn:hover { color: var(--primary-deep); border-color: var(--primary); }

    .seasonal-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 1rem;
    }

    .season-card {
      min-height: 190px;
      border-radius: var(--radius-md);
      overflow: hidden;
      position: relative;
      box-shadow: var(--shadow);
      display: grid;
      align-items: end;
      color: white;
      padding: 1rem;
      font-weight: 700;
      background-size: cover;
      background-position: center;
    }

    .season-card::before {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(180deg, transparent 35%, oklch(22% 0.03 40 / 0.6));
    }

    .season-card span { position: relative; z-index: 1; }

    .categories-grid {
      display: grid;
      grid-template-columns: repeat(5, minmax(120px, 1fr));
      gap: 1rem;
    }

    .category-card {
      border-radius: var(--radius-md);
      overflow: hidden;
      min-height: 180px;
      position: relative;
      cursor: pointer;
      background-size: cover;
      background-position: center;
      transform: translateY(0) scale(1);
      transition: transform 0.25s ease;
      box-shadow: var(--shadow);
    }

    .category-card::after {
      content: attr(data-name);
      position: absolute;
      inset: auto 0 0 0;
      padding: 1rem 0.8rem;
      font-weight: 700;
      color: white;
      background: linear-gradient(180deg, transparent, oklch(20% 0.02 145 / 0.72));
      transform: translateY(14px);
      transition: transform 0.25s ease;
    }

    .category-card:hover {
      transform: scale(1.03);
    }

    .category-card:hover::after {
      transform: translateY(0);
    }

    .store-box, .newsletter-box {
      background: var(--surface);
      border-radius: var(--radius-lg);
      border: 1px solid var(--line);
      box-shadow: var(--shadow);
      padding: 1.4rem;
    }

    .input-row {
      display: flex;
      gap: 0.6rem;
      flex-wrap: wrap;
      margin-top: 1rem;
    }

    input {
      flex: 1;
      min-width: 220px;
      padding: 0.75rem 0.9rem;
      border-radius: 999px;
      border: 1px solid var(--line);
      font: inherit;
    }

    .result-list {
      margin-top: 1rem;
      display: grid;
      gap: 0.7rem;
    }

    .store-item {
      border: 1px solid var(--line);
      border-radius: var(--radius-sm);
      padding: 0.8rem;
      background: var(--bg-soft);
    }

    .hidden { display: none; }

    footer {
      margin-top: 2rem;
      background: oklch(30% 0.04 145);
      color: oklch(95% 0.02 95);
      padding: 2.4rem 0 1.2rem;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 1.2rem;
    }

    .footer-col h3 { font-size: 1rem; margin-bottom: 0.5rem; }
    .footer-col a { display: block; color: oklch(88% 0.01 95); margin: 0.3rem 0; font-size: 0.94rem; }
    .copy { margin-top: 1.2rem; color: oklch(84% 0.01 95); font-size: 0.9rem; }

    @media (max-width: 980px) {
      .hero-grid, .stats, .categories-grid, .footer-grid, .seasonal-grid {
        grid-template-columns: 1fr 1fr;
      }
      .categories-grid { grid-template-columns: repeat(3, 1fr); }
    }

    @media (max-width: 680px) {
      .hero-grid, .stats, .categories-grid, .footer-grid, .seasonal-grid {
        grid-template-columns: 1fr;
      }
      .nav { flex-wrap: wrap; }
      section { padding: 2.5rem 0; }
    }
  </style>
</head>
<body>
  <header>
    <div class="container nav">
      <a href="#" class="logo">
        <span class="logo-badge">🍋</span> Fresh Pantry
      </a>
      <nav class="nav-links">
        <a href="#featured">Products</a>
        <a href="#stores">Our Stores</a>
        <a href="#newsletter">Recipes</a>
        <a href="#about">About Us</a>
      </nav>
      <button class="cta-btn">Shop This Week</button>
    </div>
  </header>

  <main>
    <section class="hero" id="about">
      <div class="container hero-grid">
        <div>
          <span class="eyebrow">Neighborhood Grocery Magic ✨</span>
          <h1>Discover Everyday Deliciousness</h1>
          <p>A neighborhood grocery store offering unique, high-quality food products at great prices. Find pantry treasures, seasonal favorites, and fresh inspiration for every meal.</p>
          <div class="hero-actions">
            <button class="cta-btn">Explore Products</button>
            <button class="btn-secondary">Find a Store</button>
          </div>
        </div>
        <div class="hero-image" aria-label="Fresh produce display"></div>
      </div>
    </section>

    <section class="container">
      <div class="highlights">
        <div class="stats">
          <div class="stat"><div class="stat-value">500+</div><div class="stat-label">Stores Nationwide</div></div>
          <div class="stat"><div class="stat-value">4,000+</div><div class="stat-label">Unique Products</div></div>
          <div class="stat"><div class="stat-value">80%</div><div class="stat-label">Private Label Items</div></div>
          <div class="stat"><div class="stat-value">Weekly</div><div class="stat-label">New Items Added</div></div>
        </div>
      </div>
    </section>

    <section id="featured" class="container">
      <div class="section-head">
        <div>
          <h2>Featured Products</h2>
          <p>Fan-favorite finds with feel-good prices.</p>
        </div>
      </div>
      <div class="carousel-wrap">
        <div class="carousel" id="productCarousel">
          <article class="product-card"><img src="https://images.unsplash.com/photo-1515003197210-e0cd71810b5f?auto=format&fit=crop&w=800&q=80" alt="Organic Maple Granola"><div class="product-body"><div class="product-name">Organic Maple Granola</div><div class="price">$4.99</div></div></article>
          <article class="product-card"><img src="https://images.unsplash.com/photo-1585238342024-78d387f4a707?auto=format&fit=crop&w=800&q=80" alt="Everything But The Bagel Seasoning"><div class="product-body"><div class="product-name">Everything But The Bagel Seasoning</div><div class="price">$2.49</div></div></article>
          <article class="product-card"><img src="https://images.unsplash.com/photo-1599599810769-bcde5a160d32?auto=format&fit=crop&w=800&q=80" alt="Dark Chocolate Peanut Butter Cups"><div class="product-body"><div class="product-name">Dark Chocolate Peanut Butter Cups</div><div class="price">$3.99</div></div></article>
          <article class="product-card"><img src="https://images.unsplash.com/photo-1555949963-aa79dcee981c?auto=format&fit=crop&w=800&q=80" alt="Cauliflower Gnocchi"><div class="product-body"><div class="product-name">Cauliflower Gnocchi</div><div class="price">$2.99</div></div></article>
          <article class="product-card"><img src="https://images.unsplash.com/photo-1604908177225-74430a7bde49?auto=format&fit=crop&w=800&q=80" alt="Mandarin Orange Chicken"><div class="product-body"><div class="product-name">Mandarin Orange Chicken</div><div class="price">$5.49</div></div></article>
        </div>
        <div class="carousel-controls">
          <button class="icon-btn" id="prevBtn" aria-label="Previous products">←</button>
          <button class="icon-btn" id="nextBtn" aria-label="Next products">→</button>
        </div>
      </div>
    </section>

    <section class="container">
      <div class="section-head">
        <h2>Seasonal Picks</h2>
        <p>Limited-time flavors perfect for this season.</p>
      </div>
      <div class="seasonal-grid">
        <div class="season-card" style="background-image:url('https://images.unsplash.com/photo-1471943311424-646960669fbc?auto=format&fit=crop&w=1000&q=80')"><span>Summer Citrus Collection</span></div>
        <div class="season-card" style="background-image:url('https://images.unsplash.com/photo-1504754524776-8f4f37790ca0?auto=format&fit=crop&w=1000&q=80')"><span>Farmstand Breakfast Picks</span></div>
      </div>
    </section>

    <section class="container">
      <div class="section-head">
        <h2>Browse by Category</h2>
        <p>Hover to explore aisle favorites.</p>
      </div>
      <div class="categories-grid">
        <div class="category-card" data-name="Snacks &amp; Sweets" style="background-image:url('https://images.unsplash.com/photo-1584263347416-85a696b4eda7?auto=format&fit=crop&w=800&q=80')"></div>
        <div class="category-card" data-name="Fresh Produce" style="background-image:url('https://images.unsplash.com/photo-1488459716781-31db52582fe9?auto=format&fit=crop&w=800&q=80')"></div>
        <div class="category-card" data-name="Frozen Favorites" style="background-image:url('https://images.unsplash.com/photo-1611501275019-9b5cda994e8d?auto=format&fit=crop&w=800&q=80')"></div>
        <div class="category-card" data-name="Beverages" style="background-image:url('https://images.unsplash.com/photo-1544145945-f90425340c7e?auto=format&fit=crop&w=800&q=80')"></div>
        <div class="category-card" data-name="Dairy &amp; Cheese" style="background-image:url('https://images.unsplash.com/photo-1550583724-b2692b85b150?auto=format&fit=crop&w=800&q=80')"></div>
      </div>
    </section>

    <section class="container" id="stores">
      <div class="store-box">
        <div class="section-head" style="margin-bottom:0;">
          <div>
            <h2>Find a Fresh Pantry Near You</h2>
            <p>Enter your zip code to discover the nearest store, hours, and directions.</p>
          </div>
        </div>
        <div class="input-row">
          <input id="zipInput" type="text" placeholder="Enter your zip code" maxlength="10" />
          <button class="cta-btn" id="searchStores">Search</button>
        </div>
        <div class="result-list hidden" id="storeResults"></div>
      </div>
    </section>

    <section class="container" id="newsletter">
      <div class="newsletter-box">
        <div class="section-head" style="margin-bottom:0;">
          <div>
            <h2>Stay Fresh 🍋</h2>
            <p>Sign up for weekly deals, new product alerts, and seasonal recipes delivered to your inbox.</p>
          </div>
        </div>
        <div class="input-row">
          <input id="emailInput" type="email" placeholder="Your email address" />
          <button class="cta-btn" id="subscribeBtn">Subscribe</button>
        </div>
        <p id="subscribeMsg" class="hidden" style="margin-top:0.75rem;color:var(--primary-deep);font-weight:600;">Thanks for subscribing! Check your inbox for a welcome treat.</p>
      </div>
    </section>
  </main>

  <footer>
    <div class="container">
      <div class="footer-grid">
        <div class="footer-col"><h3>Shop</h3><a href="#">Products</a><a href="#">Seasonal Picks</a><a href="#">New Arrivals</a><a href="#">Gift Cards</a></div>
        <div class="footer-col"><h3>Company</h3><a href="#">About Us</a><a href="#">Careers</a><a href="#">Press</a><a href="#">Sustainability</a></div>
        <div class="footer-col"><h3>Help</h3><a href="#stores">Store Locator</a><a href="#">FAQs</a><a href="#">Contact Us</a><a href="#">Accessibility</a></div>
        <div class="footer-col"><h3>Follow Us</h3><a href="#">Instagram</a><a href="#">Facebook</a><a href="#">Pinterest</a><a href="#">TikTok</a></div>
      </div>
      <p class="copy">© 2024 Fresh Pantry. Discover Everyday Deliciousness.</p>
    </div>
  </footer>

  <script>
    const carousel = document.getElementById('productCarousel');
    const nextBtn = document.getElementById('nextBtn');
    const prevBtn = document.getElementById('prevBtn');

    function getScrollAmount() {
      const card = carousel.querySelector('.product-card');
      return card ? card.getBoundingClientRect().width + 16 : 260;
    }

    nextBtn.addEventListener('click', () => {
      carousel.scrollBy({ left: getScrollAmount(), behavior: 'smooth' });
    });

    prevBtn.addEventListener('click', () => {
      carousel.scrollBy({ left: -getScrollAmount(), behavior: 'smooth' });
    });

    const storeData = [
      {
        name: 'Fresh Pantry — Lincoln Park',
        address: '2140 N. Halsted St, Chicago, IL 60614',
        hours: '8am – 9pm Daily',
        distance: '0.8 mi'
      },
      {
        name: 'Fresh Pantry — Wicker Park',
        address: '1840 W. North Ave, Chicago, IL 60622',
        hours: '8am – 9pm Daily',
        distance: '1.4 mi'
      },
      {
        name: 'Fresh Pantry — Lakeview',
        address: '3745 N. Lincoln Ave, Chicago, IL 60613',
        hours: '8am – 9pm Daily',
        distance: '2.1 mi'
      }
    ];

    const zipInput = document.getElementById('zipInput');
    const searchStores = document.getElementById('searchStores');
    const storeResults = document.getElementById('storeResults');

    searchStores.addEventListener('click', () => {
      const zip = zipInput.value.trim();
      if (!zip) {
        storeResults.classList.remove('hidden');
        storeResults.innerHTML = '<div class="store-item">Please enter a zip code to search nearby stores.</div>';
        return;
      }

      storeResults.classList.remove('hidden');
      storeResults.innerHTML = storeData.map(store => `
        <div class="store-item">
          <strong>${store.name}</strong><br>
          ${store.address}<br>
          ${store.hours} · ${store.distance}
        </div>
      `).join('');
    });

    const subscribeBtn = document.getElementById('subscribeBtn');
    const emailInput = document.getElementById('emailInput');
    const subscribeMsg = document.getElementById('subscribeMsg');

    subscribeBtn.addEventListener('click', () => {
      const email = emailInput.value.trim();
      const validEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
      if (validEmail) {
        subscribeMsg.classList.remove('hidden');
        emailInput.value = '';
      } else {
        subscribeMsg.classList.remove('hidden');
        subscribeMsg.textContent = 'Please enter a valid email address.';
      }
    });
  </script>
</body>
</html>
EOF

