    .icon-btn {
      border: 1px solid var(--line);
      background: var(--surface);
      width: 42px;
      height: 42px;
      border-radius: 50%;
      font-size: 1.1rem;
      cursor: pointer;
      color: var(--text-soft);
    }

    .icon-btn:hover { color: var(--primary-deep); border-color: var(--primary); }

    .seasonal-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 1rem;
    }

    .season-card {
      min-height: 190px;
      border-radius: var(--radius-md);
      overflow: hidden;
      position: relative;
      box-shadow: var(--shadow);
      display: grid;
      align-items: end;
      color: white;
      padding: 1rem;
      font-weight: 700;
      background-size: cover;
      background-position: center;
    }

    .season-card::before {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(180deg, transparent 35%, oklch(22% 0.03 40 / 0.6));
    }

    .season-card span { position: relative; z-index: 1; }

    .categories-grid {
      display: grid;
      grid-template-columns: repeat(5, minmax(120px, 1fr));
      gap: 1rem;
    }

    .category-card {
      border-radius: var(--radius-md);
      overflow: hidden;
      min-height: 180px;
      position: relative;
      cursor: pointer;
      background-size: cover;
      background-position: center;
      transform: translateY(0) scale(1);
      transition: transform 0.25s ease;
      box-shadow: var(--shadow);
    }

    .category-card::after {
      content: attr(data-name);
      position: absolute;
      inset: auto 0 0 0;
      padding: 1rem 0.8rem;
      font-weight: 700;
      color: white;
      background: linear-gradient(180deg, transparent, oklch(20% 0.02 145 / 0.72));
      transform: translateY(14px);
      transition: transform 0.25s ease;
    }

    .category-card:hover {
      transform: scale(1.03);
    }

    .category-card:hover::after {
      transform: translateY(0);
    }

    .store-box, .newsletter-box {
      background: var(--surface);
      border-radius: var(--radius-lg);
      border: 1px solid var(--line);
      box-shadow: var(--shadow);
      padding: 1.4rem;
    }

    .input-row {
      display: flex;
      gap: 0.6rem;
      flex-wrap: wrap;
      margin-top: 1rem;
    }

    input {
      flex: 1;
      min-width: 220px;
      padding: 0.75rem 0.9rem;
      border-radius: 999px;
      border: 1px solid var(--line);
      font: inherit;
    }

    .result-list {
      margin-top: 1rem;
      display: grid;
      gap: 0.7rem;
    }

    .store-item {
      border: 1px solid var(--line);
      border-radius: var(--radius-sm);
      padding: 0.8rem;
      background: var(--bg-soft);
    }

    .hidden { display: none; }

    footer {
      margin-top: 2rem;
      background: oklch(30% 0.04 145);
      color: oklch(95% 0.02 95);
      padding: 2.4rem 0 1.2rem;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 1.2rem;
    }

    .footer-col h3 { font-size: 1rem; margin-bottom: 0.5rem; }
    .footer-col a { display: block; color: oklch(88% 0.01 95); margin: 0.3rem 0; font-size: 0.94rem; }
    .copy { margin-top: 1.2rem; color: oklch(84% 0.01 95); font-size: 0.9rem; }

    @media (max-width: 980px) {
      .hero-grid, .stats, .categories-grid, .footer-grid, .seasonal-grid {
        grid-template-columns: 1fr 1fr;
      }
      .categories-grid { grid-template-columns: repeat(3, 1fr); }
    }

    @media (max-width: 680px) {
      .hero-grid, .stats, .categories-grid, .footer-grid, .seasonal-grid {
        grid-template-columns: 1fr;
      }
      .nav { flex-wrap: wrap; }
      section { padding: 2.5rem 0; }
    }
  </style>
</head>
<body>
  <header>
