        <a href="#about">About Us</a>
      </nav>
      <button class="cta-btn">Shop This Week</button>
    </div>
  </header>

  <main>
    <section class="hero" id="about">
      <div class="container hero-grid">
        <div>
          <span class="eyebrow">Neighborhood Grocery Magic ✨</span>
          <h1>Discover Everyday Deliciousness</h1>
          <p>A neighborhood grocery store offering unique, high-quality food products at great prices. Find pantry treasures, seasonal favorites, and fresh inspiration for every meal.</p>
          <div class="hero-actions">
            <button class="cta-btn">Explore Products</button>
            <button class="btn-secondary">Find a Store</button>
          </div>
        </div>
        <div class="hero-image" aria-label="Fresh produce display"></div>
      </div>
    </section>

    <section class="container">
      <div class="highlights">
        <div class="stats">
          <div class="stat"><div class="stat-value">500+</div><div class="stat-label">Stores Nationwide</div></div>
          <div class="stat"><div class="stat-value">4,000+</div><div class="stat-label">Unique Products</div></div>
          <div class="stat"><div class="stat-value">80%</div><div class="stat-label">Private Label Items</div></div>
          <div class="stat"><div class="stat-value">Weekly</div><div class="stat-label">New Items Added</div></div>
        </div>
      </div>
    </section>

    <section id="featured" class="container">
      <div class="section-head">
        <div>
          <h2>Featured Products</h2>
          <p>Fan-favorite finds with feel-good prices.</p>
        </div>
      </div>
      <div class="carousel-wrap">
        <div class="carousel" id="productCarousel">
          <article class="product-card"><img src="https://images.unsplash.com/photo-1515003197210-e0cd71810b5f?auto=format&fit=crop&w=800&q=80" alt="Organic Maple Granola"><div class="product-body"><div class="product-name">Organic Maple Granola</div><div class="price">$4.99</div></div></article>
          <article class="product-card"><img src="https://images.unsplash.com/photo-1585238342024-78d387f4a707?auto=format&fit=crop&w=800&q=80" alt="Everything But The Bagel Seasoning"><div class="product-body"><div class="product-name">Everything But The Bagel Seasoning</div><div class="price">$2.49</div></div></article>
          <article class="product-card"><img src="https://images.unsplash.com/photo-1599599810769-bcde5a160d32?auto=format&fit=crop&w=800&q=80" alt="Dark Chocolate Peanut Butter Cups"><div class="product-body"><div class="product-name">Dark Chocolate Peanut Butter Cups</div><div class="price">$3.99</div></div></article>
          <article class="product-card"><img src="https://images.unsplash.com/photo-1555949963-aa79dcee981c?auto=format&fit=crop&w=800&q=80" alt="Cauliflower Gnocchi"><div class="product-body"><div class="product-name">Cauliflower Gnocchi</div><div class="price">$2.99</div></div></article>
          <article class="product-card"><img src="https://images.unsplash.com/photo-1604908177225-74430a7bde49?auto=format&fit=crop&w=800&q=80" alt="Mandarin Orange Chicken"><div class="product-body"><div class="product-name">Mandarin Orange Chicken</div><div class="price">$5.49</div></div></article>
