        <div class="category-card" data-name="Frozen Favorites" style="background-image:url('https://images.unsplash.com/photo-1611501275019-9b5cda994e8d?auto=format&fit=crop&w=800&q=80')"></div>
        <div class="category-card" data-name="Beverages" style="background-image:url('https://images.unsplash.com/photo-1544145945-f90425340c7e?auto=format&fit=crop&w=800&q=80')"></div>
