      <div class="footer-grid">
        <div class="footer-col"><h3>Shop</h3><a href="#">Products</a><a href="#">Seasonal Picks</a><a href="#">New Arrivals</a><a href="#">Gift Cards</a></div>
        <div class="footer-col"><h3>Company</h3><a href="#">About Us</a><a href="#">Careers</a><a href="#">Press</a><a href="#">Sustainability</a></div>
        <div class="footer-col"><h3>Help</h3><a href="#stores">Store Locator</a><a href="#">FAQs</a><a href="#">Contact Us</a><a href="#">Accessibility</a></div>
