  <script>
    const carousel = document.getElementById('productCarousel');
    const nextBtn = document.getElementById('nextBtn');
    const prevBtn = document.getElementById('prevBtn');

    function getScrollAmount() {
      const card = carousel.querySelector('.product-card');
      return card ? card.getBoundingClientRect().width + 16 : 260;
    }

    nextBtn.addEventListener('click', () => {
      carousel.scrollBy({ left: getScrollAmount(), behavior: 'smooth' });
    });

    prevBtn.addEventListener('click', () => {
      carousel.scrollBy({ left: -getScrollAmount(), behavior: 'smooth' });
    });

    const storeData = [
      {
        name: 'Fresh Pantry — Lincoln Park',
        address: '2140 N. Halsted St, Chicago, IL 60614',
        hours: '8am – 9pm Daily',
        distance: '0.8 mi'
      },
      {
        name: 'Fresh Pantry — Wicker Park',
        address: '1840 W. North Ave, Chicago, IL 60622',
        hours: '8am – 9pm Daily',
        distance: '1.4 mi'
      },
      {
        name: 'Fresh Pantry — Lakeview',
        address: '3745 N. Lincoln Ave, Chicago, IL 60613',
        hours: '8am – 9pm Daily',
        distance: '2.1 mi'
      }
    ];

    const zipInput = document.getElementById('zipInput');
    const searchStores = document.getElementById('searchStores');
    const storeResults = document.getElementById('storeResults');

    searchStores.addEventListener('click', () => {
      const zip = zipInput.value.trim();
      if (!zip) {
        storeResults.classList.remove('hidden');
        storeResults.innerHTML = '<div class="store-item">Please enter a zip code to search nearby stores.</div>';
        return;
      }

      storeResults.classList.remove('hidden');
      storeResults.innerHTML = storeData.map(store => `
        <div class="store-item">
          <strong>${store.name}</strong><br>
          ${store.address}<br>
          ${store.hours} · ${store.distance}
        </div>
      `).join('');
    });

    const subscribeBtn = document.getElementById('subscribeBtn');
    const emailInput = document.getElementById('emailInput');
    const subscribeMsg = document.getElementById('subscribeMsg');

    subscribeBtn.addEventListener('click', () => {
      const email = emailInput.value.trim();
      const validEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
      if (validEmail) {
        subscribeMsg.classList.remove('hidden');
        emailInput.value = '';
      } else {
        subscribeMsg.classList.remove('hidden');
        subscribeMsg.textContent = 'Please enter a valid email address.';
      }
    });
  </script>
